-- One-time migration: positional question ids (c01-01, u1-01) → content-based ids (c01-<hash>, u1-<hash>).
-- Generated by wave-sync from the committed questions.json before/after. Contains ids only, no answers.
-- Run ONCE in Supabase (project gmeyamrlqfrabtslsweu) together with deploying the site build that ships the new
-- questions.json (the old site sends old ids, the new site sends new ids). Safe to re-run: a second run changes nothing.
-- Think Like a Scientist ids (tls-01 … tls-28) do not change.
--
-- What it does:
--   1. renames 830 b_keys rows (answers untouched),
--   2. renames the question ids inside b_attempts.answers (scores untouched), so old attempts still line up.
begin;

create temp table _qid_map (old text primary key, new text not null unique) on commit drop;

do $$
declare n_old int; n_new int;
begin
  select count(*) into n_old from public.b_keys k join _qid_map m on m.old = k.id;
  select count(*) into n_new from public.b_keys k join _qid_map m on m.new = k.id;
  if n_old = 0 and n_new = 830 then raise notice 'Already migrated: nothing to do.';
  elsif n_old <> 830 or n_new <> 0 then
    raise exception 'Unexpected b_keys state (old ids found: %, new ids found: %). Nothing changed.', n_old, n_new;
  end if;
end $$;

update public.b_keys k set id = m.new from _qid_map m where k.id = m.old;

update public.b_attempts a
   set answers = (select coalesce(jsonb_object_agg(coalesce(m.new, e.key), e.value), '{}'::jsonb)
                    from jsonb_each(a.answers) e left join _qid_map m on m.old = e.key)
 where exists (select 1 from jsonb_object_keys(a.answers) k join _qid_map m on m.old = k);

commit;

-- Check (should return 0): select count(*) from public.b_keys where id ~ '^(c\d\d|u\d)-\d\d$';
